# 3중 함수 구조 (Triple Nested)
def repeat(num_times):
    print(f"Decorator factory called with {num_times}")
    def decorator_func(func):
        print("Decorator called")
        def wrapper(*args, **kwargs):
            print("Wrapper called")
            for _ in range(num_times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator_func

@repeat(num_times=3)
def greet(name):
    print(f"Hello {name}")

def example():
    print("--- Start ---")
    greet("World")

if __name__ == '__main__':
    # 주의: @ 구문 사용 시 이미 factory와 decorator는 실행됨
    example()
